import sys as _prompt_sys
from pathlib import Path as _PromptPath
for _prompt_parent in _PromptPath(__file__).resolve().parents:
    if (_prompt_parent / 'runtime_prompt_loader.py').is_file():
        if str(_prompt_parent) not in _prompt_sys.path:
            _prompt_sys.path.insert(0, str(_prompt_parent))
        break
from runtime_prompt_loader import get_prompt as _get_prompt
import os
import json
from datetime import datetime
import psycopg2
from psycopg2.extras import RealDictCursor
from openpyxl import Workbook
PG_HOST = os.getenv('PG_HOST', '127.0.0.1')
PG_PORT = int(os.getenv('PG_PORT', '5433'))
PG_DB = os.getenv('PG_DB', 'mimiciv')
PG_USER = os.getenv('PG_USER', 'postgres')
PG_PWD = os.getenv('PG_PWD', '')
N_SAMPLE = 300
OUT_XLSX = 'non_ards_info.xlsx'
CELL_MAX_CHARS = 16000

def to_cell_str(val) -> str:
    """Convert dict/list/jsonb, etc. into strings suitable for writing to Excel, and perform length protection."""
    if val is None:
        return ''
    if isinstance(val, (dict, list)):
        s = json.dumps(val, ensure_ascii=False)
    else:
        s = str(val)
    if len(s) > CELL_MAX_CHARS:
        s = s[:CELL_MAX_CHARS] + '...(truncated)'
    return s

def main():
    conn = psycopg2.connect(host=PG_HOST, port=PG_PORT, dbname=PG_DB, user=PG_USER, password=PG_PWD)
    sql = f"WITH\n    -- ========= 0) Define exclusion list: all people with an ARDS diagnosis =========\n    --As long as there is a record of J80 or 51882/51885, you cannot enter the control group\n    excluded_ards_hadm AS (\n      SELECT DISTINCT di.hadm_id\n      FROM mimiciv_hosp.diagnoses_icd di\n      WHERE\n        (di.icd_version = 10 AND di.icd_code = 'J80')\n        OR\n        (di.icd_version = 9 AND di.icd_code IN ('51882', '51885'))\n    ),\n\n    -- ========= 1) ICU basics =========\n    icu_all AS (\n      SELECT\n        ie.subject_id, ie.hadm_id, ie.stay_id,\n        ie.intime AS icu_intime,\n        ie.outtime AS icu_outtime,\n        ie.first_careunit, ie.last_careunit\n      FROM mimiciv_icu.icustays ie\n      WHERE ie.outtime >= ie.intime + INTERVAL '24 hour'\n    ),\n\n    -- ========= 2) Screening Non-ARDS patients (Params) =========\n    params AS (\n      SELECT ia.stay_id\n      FROM icu_all ia\n      WHERE\n        --Exclude hadm_id with ARDS diagnostic records\n        ia.hadm_id NOT IN (SELECT hadm_id FROM excluded_ards_hadm)\n      ORDER BY random()\n      LIMIT{N_SAMPLE}),\n\n    -- ========= 3) Selected ICU =========\n    icu AS (\n      SELECT\n        ia.subject_id, ia.hadm_id, ia.stay_id,\n        ia.icu_intime,\n        ia.icu_outtime,\n        ia.first_careunit, ia.last_careunit\n      FROM icu_all ia\n      JOIN params p ON p.stay_id = ia.stay_id\n    ),\n\n    -- ========= 4) Window: Admission to ICU -> 24 hours after admission to ICU (MODIFIED) =========\n    win AS (\n      SELECT\n        icu.subject_id,\n        icu.hadm_id,\n        icu.stay_id,\n        icu.icu_intime,\n        icu.icu_outtime,\n        icu.first_careunit,\n        icu.last_careunit,\n\n        -- Non-ARDS has no diagnosis time, and the relevant indicators are left blank to maintain column alignment.\n        NULL::timestamp AS ards_detect_time,\n        NULL::text AS ventilation_status,\n        NULL::numeric AS peep,\n        NULL::numeric AS fio2_raw,\n        NULL::numeric AS fio2_frac,\n        NULL::numeric AS pao2_mmHg,\n        NULL::numeric AS pf_ratio,\n\n        -- ICD evidence set to empty JSON\n        '[]'::jsonb AS ards_icd_json,\n\n        icu.icu_intime AS t_start,\n\n        -- [Modification point] Window end point: admission to ICU + 24 hours (if discharged early, take ICU Outtime)\n        LEAST(icu.icu_outtime, icu.icu_intime + INTERVAL '24 hour') AS t_end\n      FROM icu\n    ),\n\n    -- ========= 5) Split by 12h: one line every 12 hours =========\n    win_days AS (\n      SELECT\n        w.subject_id,\n        w.hadm_id,\n        w.stay_id,\n        w.icu_intime,\n        w.icu_outtime,\n        w.first_careunit,\n        w.last_careunit,\n\n        w.ards_detect_time,\n        w.ventilation_status,\n        w.peep,\n        w.fio2_raw,\n        w.fio2_frac,\n        w.pao2_mmHg,\n        w.pf_ratio,\n        w.ards_icd_json,\n\n        w.t_start,\n        w.t_end,\n\n        gs.day_start,\n        -- day_end is limited to day_start + 12h\n        LEAST(w.t_end, gs.day_start + INTERVAL '12 hour') AS day_end\n      FROM win w\n      JOIN LATERAL (\n        SELECT generate_series(\n          date_trunc('day', w.t_start),\n          w.t_end, -- ensure that the sequence is generated to the end time\n          INTERVAL '12 hour' -- the step size is maintained at 12h\n        ) AS day_start\n      ) gs ON TRUE\n      WHERE LEAST(w.t_end, gs.day_start + INTERVAL '12 hour') > gs.day_start\n    ),\n\n    -- ========= 6) Various events are aggregated by time slices (using the new day_start/day_end range) =========\n    ce AS (\n      SELECT\n        wd.stay_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', ce.charttime,\n            'item_name', di.label,\n            'item_category', di.category,\n            'value', ce.value,\n            'valuenum', ce.valuenum,\n            'valueuom', ce.valueuom,\n            'warning', ce.warning\n          )\n          ORDER BY ce.charttime\n        ) AS chartevents_json\n      FROM win_days wd\n      JOIN mimiciv_icu.chartevents ce\n        ON ce.stay_id = wd.stay_id\n      LEFT JOIN mimiciv_icu.d_items di ON di.itemid = ce.itemid\n      WHERE ce.charttime >= wd.day_start AND ce.charttime < wd.day_end\n      GROUP BY wd.stay_id, wd.day_start\n    ),\n\n    le AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', le.charttime,\n            'lab_name', dli.label,\n            'fluid', dli.fluid,\n            'lab_category', dli.category,\n            'value', le.value,\n            'valuenum', le.valuenum,\n            'valueuom', le.valueuom,\n            'ref_range_lower', le.ref_range_lower,\n            'ref_range_upper', le.ref_range_upper,\n            'flag', le.flag,\n            'priority', le.priority\n          )\n          ORDER BY le.charttime\n        ) AS labevents_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.labevents le\n        ON le.hadm_id = wd.hadm_id\n      LEFT JOIN mimiciv_hosp.d_labitems dli ON dli.itemid = le.itemid\n      WHERE le.charttime >= wd.day_start AND le.charttime < wd.day_end\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    ievt AS (\n      SELECT\n        wd.stay_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', ie.starttime,\n            'endtime', ie.endtime,\n            'amount', ie.amount,\n            'amountuom', ie.amountuom,\n            'rate', ie.rate,\n            'rateuom', ie.rateuom,\n            'ordercategoryname', ie.ordercategoryname,\n            'ordercategorydescription', ie.ordercategorydescription,\n            'ordercomponenttypedescription', ie.ordercomponenttypedescription,\n            'statusdescription', ie.statusdescription\n          )\n          ORDER BY ie.starttime\n        ) AS inputevents_json\n      FROM win_days wd\n      JOIN mimiciv_icu.inputevents ie\n        ON ie.stay_id = wd.stay_id\n      WHERE ie.starttime < wd.day_end AND ie.endtime >= wd.day_start\n      GROUP BY wd.stay_id, wd.day_start\n    ),\n\n    oevt AS (\n      SELECT\n        wd.stay_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', oe.charttime,\n            'value', oe.value,\n            'valueuom', oe.valueuom\n          )\n          ORDER BY oe.charttime\n        ) AS outputevents_json\n      FROM win_days wd\n      JOIN mimiciv_icu.outputevents oe\n        ON oe.stay_id = wd.stay_id\n      WHERE oe.charttime >= wd.day_start AND oe.charttime < wd.day_end\n      GROUP BY wd.stay_id, wd.day_start\n    ),\n\n    pevt AS (\n      SELECT\n        wd.stay_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', pe.starttime,\n            'endtime', pe.endtime,\n            'procedure_name', di.label,\n            'procedure_category', di.category,\n            'value', pe.value,\n            'valueuom', pe.valueuom,\n            'location', pe.location,\n            'locationcategory', pe.locationcategory,\n            'ordercategoryname', pe.ordercategoryname,\n            'ordercategorydescription', pe.ordercategorydescription,\n            'statusdescription', pe.statusdescription\n          )\n          ORDER BY pe.starttime\n        ) AS procedureevents_json\n      FROM win_days wd\n      JOIN mimiciv_icu.procedureevents pe\n        ON pe.stay_id = wd.stay_id\n      LEFT JOIN mimiciv_icu.d_items di ON di.itemid = pe.itemid\n      WHERE pe.starttime < wd.day_end AND pe.endtime >= wd.day_start\n      GROUP BY wd.stay_id, wd.day_start\n    ),\n\n    micro AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', COALESCE(me.charttime, me.chartdate),\n            'spec_type_desc', me.spec_type_desc,\n            'test_name', me.test_name,\n            'org_name', me.org_name,\n            'ab_name', me.ab_name,\n            'interpretation', me.interpretation,\n            'quantity', me.quantity\n          )\n          ORDER BY COALESCE(me.charttime, me.chartdate)\n        ) AS microbiology_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.microbiologyevents me\n        ON me.hadm_id = wd.hadm_id\n      WHERE COALESCE(me.charttime, me.chartdate) >= wd.day_start\n        AND COALESCE(me.charttime, me.chartdate) < wd.day_end\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    rx AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', pr.starttime,\n            'stoptime', pr.stoptime,\n            'drug', pr.drug,\n            'route', pr.route,\n            'dose_val_rx', pr.dose_val_rx,\n            'dose_unit_rx', pr.dose_unit_rx,\n            'doses_per_24_hrs', pr.doses_per_24_hrs\n          )\n          ORDER BY pr.starttime\n        ) AS prescriptions_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.prescriptions pr\n        ON pr.hadm_id = wd.hadm_id\n      WHERE pr.starttime < wd.day_end AND pr.stoptime >= wd.day_start\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    pharm AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', ph.starttime,\n            'stoptime', ph.stoptime,\n            'medication', ph.medication,\n            'route', ph.route,\n            'frequency', ph.frequency,\n            'status', ph.status\n          )\n          ORDER BY ph.starttime\n        ) AS pharmacy_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.pharmacy ph\n        ON ph.hadm_id = wd.hadm_id\n      WHERE ph.starttime < wd.day_end AND ph.stoptime >= wd.day_start\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    emar AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', e.charttime,\n            'scheduletime', e.scheduletime,\n            'medication', e.medication,\n            'event_txt', e.event_txt\n          )\n          ORDER BY e.charttime\n        ) AS emar_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.emar e\n        ON e.hadm_id = wd.hadm_id\n      WHERE e.charttime >= wd.day_start AND e.charttime < wd.day_end\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    dx AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object('long_title', did.long_title)\n        ) AS diagnoses_text_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.diagnoses_icd di\n        ON di.hadm_id = wd.hadm_id\n      LEFT JOIN mimiciv_hosp.d_icd_diagnoses did\n        ON did.icd_code = di.icd_code AND did.icd_version = di.icd_version\n      WHERE did.long_title IS NOT NULL\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    px AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object('chartdate', pi.chartdate, 'long_title', dip.long_title)\n          ORDER BY pi.chartdate\n        ) AS procedures_text_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.procedures_icd pi\n        ON pi.hadm_id = wd.hadm_id\n      LEFT JOIN mimiciv_hosp.d_icd_procedures dip\n        ON dip.icd_code = pi.icd_code AND dip.icd_version = pi.icd_version\n      WHERE dip.long_title IS NOT NULL\n      GROUP BY wd.hadm_id, wd.day_start\n    )\n\n    SELECT\n      -- Primary key column\n      wd.subject_id,\n      wd.hadm_id,\n      wd.stay_id,\n\n      -- Timeline and departments\n      wd.icu_intime,\n      wd.icu_outtime,\n      wd.first_careunit,\n      wd.last_careunit,\n\n      -- General window (admission to ICU -> 48h)\n      wd.t_start,\n      wd.ards_detect_time AS ards_detect_time,\n      wd.t_end AS window_end_time,\n\n      -- Branch according to 12h\n      wd.day_start AS day_start,\n      wd.day_end AS day_end,\n\n      -- ARDS key evidence (Non-ARDS is empty)\n      wd.ventilation_status,\n      wd.peep,\n      wd.fio2_raw,\n      wd.fio2_frac,\n      wd.pao2_mmHg,\n      wd.pf_ratio,\n\n      -- ICD side evidence (Non-ARDS is an empty array)\n      wd.ards_icd_json,\n\n      -- Various JSON arrays (aggregated by time slice)\n      COALESCE(ce.chartevents_json, '[]'::jsonb) AS chartevents_json,\n      COALESCE(le.labevents_json, '[]'::jsonb) AS labevents_json,\n      COALESCE(ievt.inputevents_json, '[]'::jsonb) AS inputevents_json,\n      COALESCE(oevt.outputevents_json, '[]'::jsonb) AS outputevents_json,\n      COALESCE(pevt.procedureevents_json, '[]'::jsonb) AS procedureevents_json,\n      COALESCE(micro.microbiology_json, '[]'::jsonb) AS microbiology_json,\n      COALESCE(rx.prescriptions_json, '[]'::jsonb) AS prescriptions_json,\n      COALESCE(pharm.pharmacy_json, '[]'::jsonb) AS pharmacy_json,\n      COALESCE(emar.emar_json, '[]'::jsonb) AS emar_json,\n      COALESCE(dx.diagnoses_text_json, '[]'::jsonb) AS diagnoses_text_json,\n      COALESCE(px.procedures_text_json, '[]'::jsonb) AS procedures_text_json\n    FROM win_days wd\n    LEFT JOIN ce ON ce.stay_id = wd.stay_id AND ce.day_start = wd.day_start\n    LEFT JOIN le ON le.hadm_id = wd.hadm_id AND le.day_start = wd.day_start\n    LEFT JOIN ievt ON ievt.stay_id = wd.stay_id AND ievt.day_start = wd.day_start\n    LEFT JOIN oevt ON oevt.stay_id = wd.stay_id AND oevt.day_start = wd.day_start\n    LEFT JOIN pevt ON pevt.stay_id = wd.stay_id AND pevt.day_start = wd.day_start\n    LEFT JOIN micro ON micro.hadm_id = wd.hadm_id AND micro.day_start = wd.day_start\n    LEFT JOIN rx ON rx.hadm_id = wd.hadm_id AND rx.day_start = wd.day_start\n    LEFT JOIN pharm ON pharm.hadm_id = wd.hadm_id AND pharm.day_start = wd.day_start\n    LEFT JOIN emar ON emar.hadm_id = wd.hadm_id AND emar.day_start = wd.day_start\n    LEFT JOIN dx ON dx.hadm_id = wd.hadm_id AND dx.day_start = wd.day_start\n    LEFT JOIN px ON px.hadm_id = wd.hadm_id AND px.day_start = wd.day_start\n    ORDER BY wd.stay_id, wd.day_start;"
    print(_get_prompt('experiments/public_mimic/data_extraction/get_no_ards_info.py::inline_L460', locals()))
    with conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(sql)
        rows = cur.fetchall()
    print(f'>>> SQL query completed, return{len(rows)}records')
    conn.close()
    wb = Workbook(write_only=True)
    ws = wb.create_sheet('non_ards_llm')
    if not rows:
        ws.append(['no rows returned'])
        wb.save(OUT_XLSX)
        print(f'Saved: {OUT_XLSX} (empty result)')
        return
    headers = list(rows[0].keys())
    ws.append(headers)
    total = len(rows)
    print('>>> Start writing to Excel...')
    for i, r in enumerate(rows, start=1):
        ws.append([to_cell_str(r.get(h)) for h in headers])
        if i % 100 == 0:
            print(f'Writing progress:{i}/{total} ({i / total:.0%})')
    wb.save(OUT_XLSX)
    print(f'>>> Done! Saved files:{OUT_XLSX}')
if __name__ == '__main__':
    main()
